import Link from "next/link";
import { prisma } from "@/lib/db";
import { formatRupees } from "@/lib/money";
import { saveProductPrice } from "./actions";

export const dynamic = "force-dynamic";

const UNIT_LABEL: Record<string, string> = {
  KG: "per kg",
  L: "per litre",
  PIECE: "per piece",
};

export default async function ProductsPage() {
  const products = await prisma.product.findMany({
    orderBy: [{ category: "asc" }, { name: "asc" }],
    select: { id: true, name: true, nameHi: true, category: true, unit: true, pricePerUnit: true },
  });

  const byCategory = new Map<string, typeof products>();
  for (const product of products) {
    const group = byCategory.get(product.category) ?? [];
    group.push(product);
    byCategory.set(product.category, group);
  }

  return (
    <main className="mx-auto flex max-w-2xl flex-col gap-6 p-6">
      <header className="flex flex-col gap-4">
        <h1 className="text-2xl font-bold">Products &amp; Prices (Saman aur Daam)</h1>
        <div className="flex gap-2">
          <Link
            href="/"
            className="rounded-lg border border-stone-300 bg-white px-4 py-2 text-sm font-medium text-stone-800 hover:bg-stone-100"
          >
            Back to Udhaar list
          </Link>
          <Link
            href="/bill/new"
            className="rounded-lg border border-stone-300 bg-white px-4 py-2 text-sm font-medium text-stone-800 hover:bg-stone-100"
          >
            New Bill
          </Link>
        </div>
        <p className="text-sm text-stone-600">
          Price changes apply to new bills only. Existing bills keep their stored amounts.
        </p>
      </header>

      {products.length === 0 ? (
        <p className="rounded-xl border bg-white p-6 text-center text-stone-700">No products yet.</p>
      ) : (
        Array.from(byCategory.entries()).map(([category, items]) => (
          <section key={category} className="flex flex-col gap-3">
            <h2 className="text-lg font-semibold text-stone-800">{category}</h2>
            <ul className="flex flex-col divide-y divide-stone-200 rounded-xl border bg-white">
              {items.map((product) => (
                <li key={product.id} className="flex flex-col gap-2 p-4">
                  <div className="flex flex-col">
                    <span className="text-lg font-semibold text-stone-900">{product.name}</span>
                    {product.nameHi && <span className="text-sm text-stone-500">{product.nameHi}</span>}
                    <span className="text-sm text-stone-600">
                      {formatRupees(product.pricePerUnit)} {UNIT_LABEL[product.unit] ?? product.unit}
                    </span>
                  </div>
                  <form action={saveProductPrice} className="flex items-center gap-2">
                    <input type="hidden" name="id" value={product.id} />
                    <input
                      type="number"
                      name="price"
                      defaultValue={product.pricePerUnit}
                      min={1}
                      max={100000}
                      step={1}
                      required
                      className="min-h-12 w-32 rounded-xl border border-stone-300 bg-white px-3 text-lg text-stone-900"
                    />
                    <button
                      type="submit"
                      className="min-h-12 rounded-xl bg-stone-800 px-4 text-base font-semibold text-white"
                    >
                      Save
                    </button>
                  </form>
                </li>
              ))}
            </ul>
          </section>
        ))
      )}
    </main>
  );
}
